  if(c.message_type==s.position){const int rootX=std::int16_t(std::uint32_t(c.data.l[2])>>16),rootY=std::int16_t(c.data.l[2]);int x{},y{};::Window child{};::cell::ui::checked::translateCoordinates(d,DefaultRootWindow(d),c.window,rootX,rootY,&x,&y,&child);const double scale=editor.nativeWindowScale;t.at={x/scale,y/scale};message(d,t.source,s.status,long(c.window),t.uri&&editor.onFilesDropped?1:0,0,0,long(s.copy));return true;}
